    public sealed class BootScreenController : IUomdScreenController
    {
        private readonly UomdSceneRouter _router;
        public UomdScreenId ScreenId => UomdScreenId.Boot;

        public BootScreenController(UomdSceneRouter router) => _router = router;

        public async Awaitable OnEnterAsync(VisualElement screenRoot)
        {
            var statusLbl = new Label("Verifying base release rel_0001 & AndroidKeyStore session...");
            statusLbl.AddToClassList("uomd-body");
            screenRoot.Add(statusLbl);

            try
            {
                string savedToken = await _router.PlatformBridge.LoadEncryptedSessionTokenAsync();
                if (!string.IsNullOrEmpty(savedToken))
                {
                    _router.Api.SetSessionToken(savedToken);
                }

                string prologueJson = await _router.Patch.ReadTextAsync("entry/prologue.json");
                if (!string.IsNullOrEmpty(prologueJson))
                {
                    _router.Session.PrologueConfig = JsonUtility.FromJson<PrologueConfigDto>(prologueJson) ?? new PrologueConfigDto();
                }

                string vfxJson = await _router.Patch.ReadTextAsync("vfx/vfx_presets.json");
                if (!string.IsNullOrEmpty(vfxJson))
                {
                    var vfxPack = JsonUtility.FromJson<VfxPackDto>(vfxJson);
                    if (vfxPack != null)
                    {
                        _router.Session.VfxPack = vfxPack;
                        _router.VfxStage.LoadPresets(vfxPack);
                    }
                }
            }
            catch (Exception ex)
            {
                Debug.LogWarning($"[BootScreen] Non-fatal content warmup warning: {ex.Message}");
            }

            await _router.NavigateToAsync(UomdScreenId.Splash);
        }

        public void OnTick(float deltaTime) { }
        public void OnExit() { }
    }

