    public sealed class PrologueScreenController : IUomdScreenController
    {
        private readonly UomdSceneRouter _router;
        private readonly SubtitleSynchronizer _subtitles = new SubtitleSynchronizer();
        private int _shotIndex;
        private float _shotElapsed;
        private Label _captionLabel;
        private Label _narrationLabel;
        private Label _counterLabel;

        public UomdScreenId ScreenId => UomdScreenId.Prologue;

        public PrologueScreenController(UomdSceneRouter router) => _router = router;

        public Awaitable OnEnterAsync(VisualElement screenRoot)
        {
            _shotIndex = 0;
            _router.Audio.PlayBgmCue("bgm_prologue_before_the_road");

            var frame = new VisualElement();
            frame.AddToClassList("uomd-panel");
            frame.style.flexGrow = 1;
            frame.style.justifyContent = Justify.SpaceBetween;

            var topRow = new VisualElement();
            topRow.style.flexDirection = FlexDirection.Row;
            topRow.style.justifyContent = Justify.SpaceBetween;

            _counterLabel = new Label("PROLOGUE · SHOT 1 / 9");
            _counterLabel.AddToClassList("uomd-subtitle");
            topRow.Add(_counterLabel);

            // First-viewing no-skip contract (7207dae1): SKIP is hidden unless prologueDone is already true
            if (_router.Session.CanSkipPrologue)
            {
                var skipBtn = UomdUiKit.CreateButton("SKIP PROLOGUE", CompletePrologueAndAdvance);
                topRow.Add(skipBtn);
            }

            _captionLabel = new Label();
            _captionLabel.AddToClassList("uomd-title-md");

            var bottomBox = new VisualElement();
            bottomBox.AddToClassList("uomd-card");

            _narrationLabel = new Label();
            _narrationLabel.AddToClassList("uomd-dialogue-text");

            var nextShotBtn = UomdUiKit.CreateButton("NEXT SHOT", AdvanceShot, primary: true);
            nextShotBtn.style.marginTop = 12;
            nextShotBtn.style.alignSelf = Align.FlexEnd;

            bottomBox.Add(_narrationLabel);
            bottomBox.Add(nextShotBtn);

            frame.Add(topRow);
            frame.Add(_captionLabel);
            frame.Add(bottomBox);
            screenRoot.Add(frame);

            BindCurrentShot();
            return default;
        }

        private void BindCurrentShot()
        {
            var scenes = _router.Session.PrologueConfig?.scenes;
            int total = scenes != null && scenes.Length > 0 ? scenes.Length : 9;
            if (_shotIndex >= total)
            {
                CompletePrologueAndAdvance();
                return;
            }

            _shotElapsed = 0f;
            _counterLabel.text = $"PROLOGUE · SHOT {_shotIndex + 1} / {total}";

            if (scenes != null && _shotIndex < scenes.Length && scenes[_shotIndex] != null)
            {
                var shot = scenes[_shotIndex];
                _captionLabel.text = shot.caption_en;
                _subtitles.BeginLine(shot.text_en, Mathf.Max(3f, shot.duration_seconds), _router.Session.ReducedMotion);
            }
            else
            {
                _captionLabel.text = $"Veyrhold Chronicle #{_shotIndex + 1}";
                _subtitles.BeginLine("Before the roads filled with ash, Veyrhold measured its days in bells.", 5f, _router.Session.ReducedMotion);
            }
            _narrationLabel.text = _subtitles.Tick(0f);
        }

        private void AdvanceShot()
        {
            if (!_subtitles.IsComplete)
            {
                _subtitles.RevealImmediately();
                _narrationLabel.text = _subtitles.FullText;
                return;
            }
            _shotIndex++;
            BindCurrentShot();
        }

        private void CompletePrologueAndAdvance()
        {
            if (_router.Session.Account?.storyProgress != null)
            {
                _router.Session.Account.storyProgress.prologueDone = true;
            }
            _router.Session.ActiveStorySceneId = "t1_intro";
            _ = _router.NavigateToAsync(UomdScreenId.Story);
        }

        public void OnTick(float deltaTime)
        {
            _shotElapsed += deltaTime;
            if (_narrationLabel != null)
            {
                _narrationLabel.text = _subtitles.Tick(deltaTime);
            }
        }

        public void OnExit() { }
    }

    public sealed class StoryScreenController : IUomdScreenController
    {
        private readonly UomdSceneRouter _router;
        private readonly SubtitleSynchronizer _subtitles = new SubtitleSynchronizer();
        private StoryRunner _runner;
        private Label _speakerLabel;
        private Label _dialogueLabel;
        private VisualElement _choiceContainer;

        public UomdScreenId ScreenId => UomdScreenId.Story;

        public StoryScreenController(UomdSceneRouter router) => _router = router;

        public async Awaitable OnEnterAsync(VisualElement screenRoot)
        {
            string sceneId = _router.Session.ActiveStorySceneId;
            _router.Audio.PlayBgmCue(AudioDirector.ResolveStoryMusicCue(sceneId));

            StorySceneDto dto = null;
            try
            {
                string json = await _router.Patch.ReadTextAsync($"story/{sceneId}.json");
                if (!string.IsNullOrEmpty(json))
                {
                    dto = JsonUtility.FromJson<StorySceneDto>(json);
                }
            }
            catch
            {
                // Fallback vertical slice scene if file is in packed story bundle
            }

            dto ??= new StorySceneDto
            {
                scene_id = sceneId,
                title = "Whispering Ash Forest",
                location_id = "loc_whispering_ash_forest",
                commands = new[]
                {
                    new StoryCommandDto { op = "say", line_id = "t1_001", speaker = "fadyme", speaker_display = "Fadyme", text = "The sanctuary bell is still ringing somewhere beyond this ash.", emotion = "composed" },
                    new StoryCommandDto { op = "say", line_id = "t1_002", speaker = "mahmut", speaker_display = "Mahmut", text = "Stay behind my shield, Fadyme. Something is moving on the road.", emotion = "vigilant" },
                    new StoryCommandDto { op = "end" }
                }
            };

            _runner = new StoryRunner(dto);

            var stage = new VisualElement();
            stage.style.flexGrow = 1;
            stage.style.justifyContent = Justify.SpaceBetween;

            var topBar = new VisualElement();
            topBar.style.flexDirection = FlexDirection.Row;
            topBar.style.justifyContent = Justify.SpaceBetween;

            var sceneTitle = new Label(dto.title.ToUpperInvariant());
            sceneTitle.AddToClassList("uomd-subtitle");

            var toBattleBtn = UomdUiKit.CreateButton("PROCEED TO BATTLE", () => _ = _router.NavigateToAsync(UomdScreenId.Battle));
            topBar.Add(sceneTitle);
            topBar.Add(toBattleBtn);

            _choiceContainer = new VisualElement();
            _choiceContainer.style.alignItems = Align.Center;

            var dialogueBox = new VisualElement();
            dialogueBox.AddToClassList("uomd-panel");

            _speakerLabel = new Label("FADYME");
            _speakerLabel.AddToClassList("uomd-speaker-tag");

            _dialogueLabel = new Label();
            _dialogueLabel.AddToClassList("uomd-dialogue-text");

            var nextBtn = UomdUiKit.CreateButton("ADVANCE", StepStory, primary: true);
            nextBtn.style.marginTop = 12;
            nextBtn.style.alignSelf = Align.FlexEnd;

            dialogueBox.Add(_speakerLabel);
            dialogueBox.Add(_dialogueLabel);
            dialogueBox.Add(nextBtn);

            stage.Add(topBar);
            stage.Add(_choiceContainer);
            stage.Add(dialogueBox);
            screenRoot.Add(stage);

            StepStory();
        }

        private void StepStory()
        {
            if (!_subtitles.IsComplete)
            {
                _subtitles.RevealImmediately();
                _dialogueLabel.text = _subtitles.FullText;
                return;
            }

            if (_runner == null || _runner.Finished)
            {
                _ = _router.NavigateToAsync(UomdScreenId.Battle);
                return;
            }

            for (int guard = 0; guard < 32; guard++)
            {
                var ev = _runner.Next();
                if (ev == null || ev.type == "end")
                {
                    _ = _router.NavigateToAsync(UomdScreenId.Battle);
                    return;
                }

                if (ev.type == "line")
                {
                    _speakerLabel.text = string.IsNullOrEmpty(ev.speakerDisplay) ? "NARRATION" : ev.speakerDisplay.ToUpperInvariant();
                    _subtitles.BeginLine(ev.text, ev.holdSeconds > 0 ? ev.holdSeconds : 3.2f, _router.Session.ReducedMotion);
                    _dialogueLabel.text = _subtitles.Tick(0f);
                    return;
                }

                if (ev.type == "choice")
                {
                    _choiceContainer.Clear();
                    foreach (var opt in ev.options)
                    {
                        string optId = opt.id;
                        var btn = UomdUiKit.CreateButton(opt.text, () =>
                        {
                            _choiceContainer.Clear();
                            _runner.Choose(optId);
                            StepStory();
                        }, primary: true);
                        btn.style.marginBottom = 8;
                        _choiceContainer.Add(btn);
                    }
                    return;
                }
            }
        }

        public void OnTick(float deltaTime)
        {
            if (_dialogueLabel != null)
            {
                _dialogueLabel.text = _subtitles.Tick(deltaTime);
            }
        }

        public void OnExit() { }
    }

    public sealed class BattleScreenController : IUomdScreenController
    {
        private readonly UomdSceneRouter _router;
        private BattleSimulator _sim;
        private Label _battleLogLabel;
        private Label _turnStatusLabel;

        public UomdScreenId ScreenId => UomdScreenId.Battle;

        public BattleScreenController(UomdSceneRouter router) => _router = router;

        public Awaitable OnEnterAsync(VisualElement screenRoot)
        {
            _router.Audio.PlayBgmCue(AudioDirector.ResolveBattleMusicCue(_router.Session.ActiveBattleEncounterId, false));

            var fadymeStats = UomdStatMath.ComputeHeroStats("TACTICIAN", 10, 1);
            var mahmutStats = UomdStatMath.ComputeHeroStats("VANGUARD", 10, 1);
            var enemyStats = UomdStatMath.ComputeHeroStats("EXECUTIONER", 8, 0);

            var units = new List<CombatUnitState>
            {
                new CombatUnitState
                {
                    instanceId = "ally_mahmut", unitId = "mahmut", name = "Mahmut", side = BattleSide.Player, slot = 1,
                    hp = mahmutStats.Hp, maxHp = mahmutStats.Hp, atk = mahmutStats.Atk, def = mahmutStats.Def, spd = mahmutStats.Spd,
                    critRate = mahmutStats.CritRate, critDmg = mahmutStats.CritDmg
                },
                new CombatUnitState
                {
                    instanceId = "ally_fadyme", unitId = "fadyme", name = "Fadyme", side = BattleSide.Player, slot = 3,
                    hp = fadymeStats.Hp, maxHp = fadymeStats.Hp, atk = fadymeStats.Atk, def = fadymeStats.Def, spd = fadymeStats.Spd,
                    critRate = fadymeStats.CritRate, critDmg = fadymeStats.CritDmg
                },
                new CombatUnitState
                {
                    instanceId = "enemy_hound_1", unitId = "ash_hound", name = "Ash Hound", side = BattleSide.Enemy, slot = 1,
                    hp = enemyStats.Hp, maxHp = enemyStats.Hp, atk = enemyStats.Atk, def = enemyStats.Def, spd = enemyStats.Spd
                }
            };

            _sim = new BattleSimulator(_router.Session.ActiveBattleEncounterId, 0x13572468u, units);

            var container = new VisualElement();
            container.AddToClassList("uomd-panel");
            container.style.flexGrow = 1;
            container.style.justifyContent = Justify.SpaceBetween;

            var hudTop = new VisualElement();
            hudTop.style.flexDirection = FlexDirection.Row;
            hudTop.style.justifyContent = Justify.SpaceBetween;

            _turnStatusLabel = new Label($"5v5 TACTICAL STAGE · HUD: {_router.Session.BattleHudLayout.ToUpperInvariant()}");
            _turnStatusLabel.AddToClassList("uomd-title-md");

            var layoutBtn = UomdUiKit.CreateButton("CYCLE HUD LAYOUT", () =>
            {
                _router.Session.BattleHudLayout = _router.Session.BattleHudLayout switch
                {
                    "afk_faithful" => "current",
                    "current" => "arena_lite",
                    _ => "afk_faithful"
                };
                _turnStatusLabel.text = $"5v5 TACTICAL STAGE · HUD: {_router.Session.BattleHudLayout.ToUpperInvariant()}";
            });

            hudTop.Add(_turnStatusLabel);
            hudTop.Add(layoutBtn);

            _battleLogLabel = new Label("Mahmut and Fadyme stand ready on the Ash Road.");
            _battleLogLabel.AddToClassList("uomd-body");

            var actionRow = new VisualElement();
            actionRow.style.flexDirection = FlexDirection.Row;

            var basicBtn = UomdUiKit.CreateButton("BASIC ATTACK", () => StepManualTurn(BattleActionKind.Basic));
            basicBtn.style.marginRight = 8;

            var activeBtn = UomdUiKit.CreateButton("ACTIVE SKILL", () => StepManualTurn(BattleActionKind.Active));
            activeBtn.style.marginRight = 8;

            var ultBtn = UomdUiKit.CreateButton("ULTIMATE", () => StepManualTurn(BattleActionKind.Ultimate), primary: true);
            ultBtn.style.marginRight = 8;

            var autoBtn = UomdUiKit.CreateButton("AUTO SIMULATE & VERIFY", CompleteBattleAuto, primary: true);

            actionRow.Add(basicBtn);
            actionRow.Add(activeBtn);
            actionRow.Add(ultBtn);
            actionRow.Add(autoBtn);

            container.Add(hudTop);
            container.Add(_battleLogLabel);
            container.Add(actionRow);
            screenRoot.Add(container);
            return default;
        }

        private void StepManualTurn(BattleActionKind kind)
        {
            if (_sim == null || _sim.IsFinished)
            {
                CompleteBattleAuto();
                return;
            }

            var actor = _sim.AdvanceToNextActor();
            if (actor != null)
            {
                _sim.ExecuteTurn(actor, kind);
                _router.VfxStage.PlayPreset("vfx_basic_slash", Vector3.left * 2f, Vector3.right * 2f, _router.Session.ReducedMotion, _router.Session.ReduceFlash);
                _battleLogLabel.text = $"Turn {_sim.CurrentTurn}: {actor.name} executed {kind}.";
            }

            if (_sim.IsFinished)
            {
                CompleteBattleAuto();
            }
        }

        private void CompleteBattleAuto()
        {
            var outcome = _sim.RunFullAutoSimulation();
            _router.Session.Account.tutorialStep = Math.Max(_router.Session.Account.tutorialStep, 3);
            _ = _router.NavigateToAsync(outcome.victory ? UomdScreenId.Finish : UomdScreenId.Home);
        }

        public void OnTick(float deltaTime) { }
        public void OnExit() { }
    }

